const fs = require('fs');
const d = require('docx');
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun, AlignmentType, HeadingLevel,
  WidthType, ShadingType, BorderStyle, PageBreak, Footer, PageNumber, LevelFormat } = d;
const S = JSON.parse(fs.readFileSync('results/summary.json'));
const FONT = 'Cambria', BLACK = '000000';
const f = (x, n = 2) => Number(x).toFixed(n);
const money = x => '$' + Math.round(x).toLocaleString('en-US');

// inline markup: **bold**, *italic*
function runs(text, base = {}) {
  return text.split(/(\*\*[^*]+\*\*|\*[^*]+\*)/).filter(Boolean).map(t => {
    if (t.startsWith('**')) return new TextRun({ text: t.slice(2, -2), bold: true, font: FONT, color: BLACK, ...base });
    if (t.startsWith('*')) return new TextRun({ text: t.slice(1, -1), italics: true, font: FONT, color: BLACK, ...base });
    return new TextRun({ text: t, font: FONT, color: BLACK, ...base });
  });
}
const P = (t, o = {}) => new Paragraph({ alignment: AlignmentType.JUSTIFIED, spacing: { after: 140, line: 300 }, children: runs(t), ...o });
const H1 = t => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text: t, font: FONT, color: BLACK })] });
const H2 = t => new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: t, font: FONT, color: BLACK })] });
const B = t => new Paragraph({ numbering: { reference: 'bul', level: 0 }, alignment: AlignmentType.JUSTIFIED, spacing: { after: 80, line: 290 }, children: runs(t) });
const CAP = t => new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 60, after: 200 }, keepLines: true, children: runs(t, { size: 20 }) });
const TCAP = t => new Paragraph({ alignment: AlignmentType.LEFT, spacing: { before: 160, after: 80 }, keepNext: true, children: runs(t, { size: 20 }) });
function FIG(file, wIn, ratio, cap) {
  const w = Math.round(wIn * 96);
  return [new Paragraph({ alignment: AlignmentType.CENTER, keepNext: true, spacing: { before: 120, after: 0 },
    children: [new ImageRun({ type: 'png', data: fs.readFileSync('plots/' + file), transformation: { width: w, height: Math.round(w * ratio) } })] }), CAP(cap)];
}
const bd = { style: BorderStyle.SINGLE, size: 4, color: BLACK };
const borders = { top: bd, bottom: bd, left: bd, right: bd };
function TBL(widths, rows, boldRows = []) {
  const total = widths.reduce((a, b) => a + b, 0);
  return new Table({ width: { size: total, type: WidthType.DXA }, columnWidths: widths, alignment: AlignmentType.CENTER,
    rows: rows.map((r, i) => new TableRow({ tableHeader: i === 0, cantSplit: true, children: r.map((c, j) => new TableCell({
      borders, width: { size: widths[j], type: WidthType.DXA }, margins: { top: 50, bottom: 50, left: 100, right: 100 },
      shading: i === 0 ? { fill: 'D9D9D9', type: ShadingType.CLEAR, color: 'auto' } : undefined,
      children: [new Paragraph({ alignment: j === 0 ? AlignmentType.LEFT : AlignmentType.CENTER,
        children: [new TextRun({ text: String(c), font: FONT, color: BLACK, size: 20, bold: i === 0 || boldRows.includes(i) })] })] })) })) });
}
const SP = () => new Paragraph({ spacing: { after: 60 }, children: [] });
const img = {}; // aspect ratios
const sizeOf = p => { const b = fs.readFileSync('plots/' + p); return b.readUInt32BE(20) / b.readUInt32BE(16); };

S.err = JSON.parse(fs.readFileSync('results/err_recommended.json'));
const R = S.results, C = S.costs, I = S.interval;
const arima = S.arima_name, four = 'ARIMA(2,0,1) + annual Fourier', sar = 'SARIMA(1,1,1)(1,0,1,7)';
const base = C['No forecast (climatology)'].total;

// ---------------- content ----------------
const c = [];
// Title page
c.push(new Paragraph({ spacing: { before: 2400, after: 200 }, alignment: AlignmentType.CENTER, children: runs('Time-Series Forecasting Project', { size: 44, bold: true }) }));
c.push(new Paragraph({ spacing: { after: 600 }, alignment: AlignmentType.CENTER, children: runs('Daily Minimum Temperature Forecasting for Heating Planning', { size: 30 }) }));
['Course: Pattern Recognition / Time-Series Forecasting', 'Group: Taha Shabbir & Sivakumar Vijayan', 'Submission date: November 2026',
 'Code and data: [insert GitHub repository link]'].forEach(t =>
  c.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 100 }, children: runs(t, { size: 24 }) })));
c.push(new Paragraph({ spacing: { before: 1400, after: 120 }, children: runs('AI disclaimer', { bold: true, size: 24 }) }));
c.push(P('AI tools were used in this project to write and debug the Python analysis code, to produce the figures, and to help draft, expand and edit the text of this report. The dataset, the decision problem and the cost assumptions were chosen by the authors. Every number quoted in the report comes from running the code in our repository on the Melbourne daily minimum temperature series; the run is seeded, so the files in the results folder can be regenerated and checked against the text. The authors have reviewed the report and take responsibility for its content and conclusions.'));
c.push(new Paragraph({ children: [new PageBreak()] }));

// Management summary (one page)
c.push(H1('Management Summary'));
const MS = t => P(t, { spacing: { after: 110, line: 276 } });
c.push(MS(`**Problem.** A facility that must be kept above 8 °C overnight (a greenhouse, a cold-sensitive store, a heated building) decides every afternoon how much heating to schedule for the coming night. Scheduled heat costs $12 per degree below 8 °C. Heat that has to be added in the night because the plan was too small costs 2.5 times as much, $30 per degree. The decision we want to improve is how many degrees of heating to book each afternoon.`));
c.push(MS(`**Recommendation.** Use the ${four} model for the nightly point forecast and book heating for max(8 °C − forecast, 0) degrees. On the ${S.split.test[0]}-day test period it had the lowest error of the nine models we compared (RMSE ${f(R[four].RMSE)} °C, MAE ${f(R[four].MAE)} °C, R² ${f(R[four].R2, 3)}). The tuned RNN and LSTM reached RMSE ${f(R.RNN.RMSE)} °C, no better than the linear models, so the simpler model is the one to run. Keep the pair of quantile LSTMs as a risk indicator: their 95% interval covered ${f(I.PICP * 100, 1)}% of test nights with a mean width of ${f(I.MPIW, 1)} °C.`));
c.push(MS(`**Expected saving.** Planning with no forecast cost ${money(base)} over the test period, all of it emergency heat. Planning with the recommended model cost ${money(C[four].total)}, a saving of ${money(base - C[four].total)} (${f((base - C[four].total) / base * 100, 1)}%), or about ${money((base - C[four].total) / S.split.test[0] * 365)} a year per unit of heating load. Emergency call-outs fell from ${C['No forecast (climatology)'].emerg_nights} nights to ${C[four].emerg_nights}. A perfect forecast would have cost ${money(C['Perfect foresight'].total)}, so the model captures about ${f((base - C[four].total) / (base - C['Perfect foresight'].total) * 100, 0)}% of the saving that is theoretically available.`));
c.push(MS(`**Risk.** The forecast is off by ${f(R[four].MAE, 1)} °C on a typical night, and on one night in twenty by more than ${f(S.err.p95_abs, 1)} °C. The worst miss in the test period was ${S.err.worst_date}: the forecast was ${f(S.err.worst_pred, 1)} °C and the night fell to ${f(S.err.worst_actual, 1)} °C, which cost $${Math.round(S.err.worst_short * 30)} in emergency heat for that single night. Booking heat to the lower bound of the interval every night cuts emergency nights to ${C['Lower bound every night (tau = 0.025)'].emerg_nights} but raises the total bill to ${money(C['Lower bound every night (tau = 0.025)'].total)}. That only pays when an unplanned cold night costs more than about 8 times the normal rate, for example when a crop would be lost. For ordinary operations the point forecast is the cheaper rule.`));
c.push(new Paragraph({ children: [new PageBreak()] }));

// 1
c.push(H1('1. Introduction and Decision Context'));
c.push(P('This project forecasts the daily minimum temperature in Melbourne one day ahead and turns each forecast into a heating decision. We chose the series because the overnight minimum is the number that drives the cost of keeping a space warm: it is the coldest point the heating system has to cover, and it is known only after the night is over.'));
c.push(P('The decision is made once a day. Each afternoon the operator books heating capacity for the coming night. Booking in advance is cheap because fuel, boiler output or off-peak electricity can be arranged at the normal rate. If the night turns out colder than the plan allowed for, the gap has to be closed at short notice with stand-by heaters or peak-rate energy, which is more expensive. If the night turns out warmer, the heat that was booked is wasted.'));
c.push(P('We use a deliberately simple cost model so that every forecast can be converted into money:'));
c.push(B('The space must be held at or above 8 °C. The heating need on a night is max(8 − actual minimum, 0) degrees.'));
c.push(B('Planned heating costs $12 per degree. The plan is max(8 − forecast minimum, 0) degrees.'));
c.push(B('Any shortfall between need and plan is covered by emergency heating at 2.5 times the normal rate, $30 per degree.'));
c.push(P('Under these rules a forecast that is too warm leads to an emergency charge and a forecast that is too cold leads to wasted planned heat. The two errors do not cost the same, and that asymmetry matters later when we ask which quantile of the forecast distribution the operator should plan to. The 8 °C threshold, the $12 rate and the 2.5 multiplier are assumptions, not measured prices. We test how the recommendation changes when the multiplier changes in Section 7.'));
c.push(P('The report follows the task list of the project brief. Section 2 analyses the data. Section 3 fits the classical linear models. Section 4 tunes and tests the RNN and LSTM. Section 5 builds a 95% prediction interval from two quantile LSTMs. Sections 6 and 7 convert the forecasts into costs and quantify the risk, and Section 8 judges the result from a management point of view.'));

// 2
c.push(H1('2. Data and Exploratory Analysis'));
c.push(H2('2.1 Source and cleaning'));
c.push(P(`The data are the daily minimum temperatures recorded in Melbourne, Australia, from 1 January 1981 to 31 December 1990, originally published by the Australian Bureau of Meteorology and widely used as a teaching dataset. The raw file has 3,650 rows. Ten calendar years with two leap years should give 3,652 days, and a check of the dates showed that 31 December 1984 and 31 December 1988 were missing. We inserted both dates and filled them by linear interpolation between the neighbouring days (14.85 °C and 14.20 °C). The cleaned file therefore has ${S.n.toLocaleString('en-US')} observations on a regular daily index, which the ARIMA and seasonal routines require.`));
c.push(H2('2.2 Descriptive statistics'));
c.push(P(`The mean of the series is ${f(S.mean, 1)} °C and the standard deviation is ${f(S.std, 1)} °C. The lowest value is ${f(S.min, 1)} °C and the highest ${f(S.max, 1)} °C. Figure 1 shows the whole decade with a 30-day rolling mean and the 8 °C threshold. The series crosses the threshold every winter: ${S.days_below_8} of the ${S.n.toLocaleString('en-US')} nights (${f(S.days_below_8 / S.n * 100, 1)}%) were below 8 °C, so the heating decision is a live one for roughly a quarter of the year.`));
FIG('00_series.png', 6.5, sizeOf('00_series.png'), '**Figure 1.** Daily minimum temperature, 1981–1990, with 30-day rolling mean and the 8 °C heating threshold.').forEach(x => c.push(x));
c.push(P('Table 1 gives the monthly profile. Because Melbourne is in the southern hemisphere the coldest months are June to August. July has a mean minimum of 6.7 °C against 15.4 °C in February, a swing of almost 9 °C. The spread within a month is fairly constant at 2.3 to 3.2 °C, which tells us that the day-to-day uncertainty is of similar size in winter and summer. The minimum column shows that nights at or near 0 °C occurred only in June and July.'));
c.push(TCAP('**Table 1.** Monthly statistics of the daily minimum temperature (°C), 1981–1990.'));
const mn = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
c.push(TBL([1500, 620, 620, 620, 620, 620, 620, 620, 620, 620, 620, 620, 620], [
  ['', ...mn],
  ...['mean', 'std', 'min', 'max'].map(k => [{ mean: 'Mean', std: 'Std. dev.', min: 'Minimum', max: 'Maximum' }[k], ...mn.map((_, i) => f(S.monthly[k][String(i + 1)], 1))])]));
c.push(SP());
c.push(H2('2.3 Decomposition into trend, seasonality and remainder'));
c.push(P(`We applied an additive decomposition with a period of 365 days (Figure 2). An additive form is appropriate because the size of the seasonal swing does not grow with the level of the series.`));
FIG('01_decomposition.png', 6.3, sizeOf('01_decomposition.png'), '**Figure 2.** Additive decomposition of the series (period = 365 days).').forEach(x => c.push(x));
c.push(P(`**Trend.** The trend component stays between ${f(S.decomp.trend_min, 1)} and ${f(S.decomp.trend_max, 1)} °C over the whole decade. The annual means confirm this: the coldest year was 1984 (10.6 °C) and the warmest 1988 (12.0 °C). There is a dip in the mid-1980s and a rise towards 1988, but no steady drift up or down. For a one-day-ahead forecast a movement of this size is negligible.`));
c.push(P(`**Seasonality.** The seasonal component runs from ${f(S.decomp.seas_min, 1)} °C in mid-winter to +${f(S.decomp.seas_max, 1)} °C in late summer. It accounts for ${f(S.decomp.var_share_seasonal * 100, 0)}% of the variance of the series. The estimated seasonal curve is jagged because each day of the year is averaged over only ten values; the underlying shape is a smooth single wave, which is why two pairs of sine and cosine terms are enough to describe it in Section 3.`));
c.push(P(`**Remainder.** The remainder has a standard deviation of ${f(S.decomp.resid_std, 2)} °C and carries ${f(S.decomp.var_share_resid * 100, 0)}% of the variance. It is not white noise. Its lag-1 autocorrelation is ${f(S.decomp.resid_acf1)}, falling to ${f(S.decomp.resid_acf2)} at lag 2 and ${f(S.decomp.resid_acf7)} at lag 7, and a Ljung–Box test at 10 lags rejects independence with a p-value that is effectively zero. This is the most useful finding of the decomposition for our purpose: after the calendar has been accounted for, yesterday's deviation from the seasonal norm still says a good deal about today's, but the information fades within about a week. A model that combines the season with a short memory of recent days should therefore do well, and a remainder of about 2.5 °C sets a rough floor on the error any such model can reach.`));
c.push(H2('2.4 Autocorrelation'));
c.push(P(`Figure 3 shows the autocorrelation function (ACF) and partial autocorrelation function (PACF) for the first 60 lags. The ACF starts at ${f(S.acf['1'])} at lag 1, drops to ${f(S.acf['2'])} at lag 2 and then declines very slowly: it is still ${f(S.acf['7'])} at lag 7, ${f(S.acf['30'])} at lag 30 and ${f(S.acf['60'])} at lag 60. The sharp fall over the first two or three lags is the weather memory seen in the remainder. The long, slow tail is not memory in the same sense. It is produced by the season: two days a month apart are both in the same part of the year and are therefore both warm or both cold.`));
FIG('02_acf_pacf.png', 6.5, sizeOf('02_acf_pacf.png'), '**Figure 3.** ACF and PACF of the original series, lags 0–60. Shaded band: 95% confidence limits.').forEach(x => c.push(x));
c.push(P(`Figure 4 extends the ACF to 800 lags and makes this plain. The correlation falls to ${f(S.acf['182'])} at a lag of half a year, returns to ${f(S.acf['365'])} at one year and ${f(S.acf['730'])} at two years. We looked for a weekly pattern, since many daily series have one, and found none: the ACF has no bump at lags 7, 14 or 21. This is expected for a physical quantity that does not depend on the working week, and it matters for the SARIMA model in Section 3.5.`));
FIG('02b_acf_long.png', 6.3, sizeOf('02b_acf_long.png'), '**Figure 4.** ACF over 800 lags. Dotted lines mark half-year multiples (182, 365, 547 and 730 days).').forEach(x => c.push(x));
c.push(P(`The PACF is dominated by lag 1 (${f(S.pacf['1'])}). After that the values are small but they do not vanish at once: lag 3 is ${f(S.pacf['3'])}, lag 7 is ${f(S.pacf['7'])}, lag 9 is ${f(S.pacf['9'])}, against a 95% band of ±${f(S.pacf_ci, 3)}. They remain outside the band up to lag 13, and lag 14 (${f(S.pacf['14'], 3)}) is the first to fall just inside. These two plots decide the orders of the MA and AR models in the next section.`));
c.push(H2('2.5 Stationarity'));
c.push(P(`We tested for a unit root with the Augmented Dickey–Fuller (ADF) test. On the original series the statistic is ${f(S.adf_original.stat)} with ${S.adf_original.lags} lags, below the 1% critical value of ${f(S.adf_original.crit1)} (p = ${f(S.adf_original.p, 4)}). The null hypothesis of a unit root is rejected. As a cross-check we ran the KPSS test, whose null hypothesis is the opposite one (stationarity). Its statistic is ${f(S.kpss_original.stat, 3)}, far below the 10% critical value of 0.347, so stationarity is not rejected. The two tests agree.`));
c.push(P(`This needs careful reading. The tests say that the series has no stochastic trend: it does not wander away and it returns to the same level every year. They do not say that the mean is the same on every day, and Figure 1 shows that it is not. The series is stationary around a fixed seasonal cycle. There are two ways to deal with the cycle, and we show both. The first is differencing. After one difference the ADF statistic is ${f(S.adf_diff.stat, 1)}, an even stronger rejection, and the differenced series has no visible seasonal pattern because the season changes very little from one day to the next. The second is to keep the series in levels and model the cycle directly with sine and cosine terms. Section 3.4 compares the two.`));
c.push(H2('2.6 Train, validation and test split'));
c.push(P(`The series was split in time order with no shuffling: the first 70% for training, the next 15% for validation and the last 15% for testing (Table 2 and Figure 5). Every model in this report uses this split. Model parameters are estimated on the training set only. The validation set is used to choose neural network settings and to stop training. The test set is used once, for the final numbers.`));
c.push(TCAP('**Table 2.** Chronological split of the series.'));
c.push(TBL([2000, 1500, 2200, 2200], [['Set', 'Days', 'From', 'To'],
  ['Training', S.split.train[0], S.split.train[1], S.split.train[2]], ['Validation', S.split.val[0], S.split.val[1], S.split.val[2]], ['Test', S.split.test[0], S.split.test[1], S.split.test[2]]]));
c.push(SP());
FIG('02c_split.png', 6.3, sizeOf('02c_split.png'), '**Figure 5.** The three sets on the time axis.').forEach(x => c.push(x));
c.push(P(`The test set runs from July 1989 to December 1990. It contains one full winter (1990) and the second half of another (1989), with ${S.test_stats.days_below_8} nights below 8 °C and a lowest value of ${f(S.test_stats.min, 1)} °C. Its mean (${f(S.test_stats.mean, 1)} °C) is almost identical to the training mean (${f(S.train_mean, 1)} °C), so the models are not being asked to forecast under conditions they have not seen. There are no zero values in the test set, which means MAPE is well defined. It should still be read with care, because a 2 °C error on a 4 °C night counts as 50% while the same error on a 16 °C night counts as 12.5%. For the heating decision the absolute error in degrees is the relevant measure, and we rely mainly on RMSE and MAE.`));

// 3
c.push(H1('3. Classical Linear Models'));
c.push(H2('3.1 Evaluation protocol and baselines'));
c.push(P(`All models produce one-step-ahead forecasts. For the classical models this was done as follows: the coefficients were estimated once on the training set and then frozen; the fitted model was run over the full series, and for each test day the forecast was computed from the observations up to the previous day. No coefficient was re-estimated on validation or test data. This matches how the model would be used in practice, where yesterday's reading is always available when tonight's plan is made.`));
c.push(P(`An earlier version of our analysis asked each classical model for a single forecast path covering the whole test period from the end of the training data. That is a forecast up to three years ahead, not one day ahead. Under that procedure the models quickly settle at the long-run mean and give an RMSE of about ${f(S.multi_step['MA(7)'].RMSE, 1)} °C with R² close to zero, and the differenced ARIMA drifts and does worse still (RMSE ${f(S.multi_step[arima].RMSE, 2)} °C, R² ${f(S.multi_step[arima].R2, 2)}). Those numbers made the neural networks look far superior, but the comparison was not like for like, because the networks were being given the true previous 30 days at every step. Once all models are evaluated one step ahead the picture changes completely, as Table 4 shows.`));
c.push(P(`Two baselines give the results a scale. **Climatology** forecasts the training mean (${f(S.train_mean, 1)} °C) every day; it represents planning without any forecast. **Persistence** forecasts that tonight will equal last night. Climatology has an RMSE of ${f(R.Climatology.RMSE)} °C, which is simply the standard deviation of the test set. Persistence reaches ${f(R.Persistence.RMSE)} °C. Any model worth using has to beat persistence.`));
c.push(H2('3.2 MA(7)'));
c.push(P(`A moving-average model of order q expresses today's value as the mean plus a weighted sum of the last q forecast errors. The textbook rule is to choose q as the lag after which the ACF cuts off to zero. Our ACF never cuts off (Figure 3), which is a sign that a pure MA model is not a natural fit for this series. We fixed q = 7 for a practical reason: the remainder analysis in Section 2.3 showed that the short-term dependence has died away by about one week, so seven error terms cover the memory that is not seasonal. A larger q would be chasing the slow seasonal tail, which an MA model cannot represent in any case.`));
c.push(P(`On the test set MA(7) has an RMSE of ${f(R['MA(7)'].RMSE)} °C and R² of ${f(R['MA(7)'].R2, 3)}. It beats persistence but is the weakest of the fitted models. Figure 6 shows why. The forecast follows the short swings, but because the model's memory ends after seven days it keeps being pulled towards the overall mean of 11 °C. In the winter zoom the forecast line sits above the observations for most of June to August.`));
FIG('03_ma_forecast.png', 6.5, sizeOf('03_ma_forecast.png'), '**Figure 6.** MA(7) one-step-ahead forecasts against actual values. Left: full test set. Right: winter 1990.').forEach(x => c.push(x));
c.push(H2('3.3 AR(14)'));
c.push(P(`An autoregressive model of order p regresses today's value on the previous p values. The order is read from the PACF: p is the last lag at which the partial autocorrelation is clearly different from zero. In our PACF the values stay outside the confidence band up to lag 13 and lag 14 is the first that falls inside (Section 2.4). We set p = 14, two full weeks, so that every lag with a detectable direct effect is included.`));
c.push(P(`The fitted coefficients are informative. The first is ${f(S.ar_params['ar.L1'])}, the second is ${f(S.ar_params['ar.L2'])}, and the remaining twelve are all small and positive, between 0.01 and 0.06. Lag 1 carries the weather memory. The long row of small positive weights acts as a two-week average, which is a crude estimate of the current seasonal level. This is how a model with no seasonal term still manages to follow the season: AR(14) reaches an RMSE of ${f(R['AR(14)'].RMSE)} °C and R² of ${f(R['AR(14)'].R2, 3)}, a clear improvement on MA(7), and its AIC on the training set (${f(S.aic['AR(14)'], 0)}) is much lower than that of MA(7) (${f(S.aic['MA(7)'], 0)}).`));
FIG('04_ar_forecast.png', 6.5, sizeOf('04_ar_forecast.png'), '**Figure 7.** AR(14) one-step-ahead forecasts against actual values.').forEach(x => c.push(x));
c.push(H2('3.4 ARIMA'));
c.push(P(`For ARIMA(p, d, q) we fitted all 32 combinations of p and q from 0 to 3 with d equal to 0 or 1 on the training set and ranked them by AIC. Table 3 lists the best five. ${arima} has the lowest AIC, although the top four are separated by about one AIC point and are for practical purposes equivalent. Two of the top four use d = 1 and two use d = 0, which fits the conclusion of Section 2.5: the series does not need differencing to remove a unit root, but differencing is a cheap way to make the model follow the slowly moving seasonal level.`));
c.push(TCAP('**Table 3.** Best five ARIMA orders by AIC on the training set.'));
c.push(TBL([2600, 2000], [['Order (p, d, q)', 'AIC'], ...S.arima_grid.slice(0, 5).map(g => [`(${g.p}, ${g.d}, ${g.q})`, f(g.AIC, 1)])], [1]));
c.push(SP());
c.push(P(`The residuals of ${arima} pass the Ljung–Box test at 10 and 20 lags (p = ${f(S.arima_resid_lb_p[0], 2)} and ${f(S.arima_resid_lb_p[1], 2)}), so the model has extracted the linear structure that is there. Its test RMSE is ${f(R[arima].RMSE)} °C, the same as AR(14) to two decimals, with three coefficients where AR(14) needs fifteen.`));
FIG('05_arima_forecast.png', 6.5, sizeOf('05_arima_forecast.png'), `**Figure 8.** ${arima} one-step-ahead forecasts against actual values.`).forEach(x => c.push(x));
c.push(H2('3.5 Seasonal models'));
c.push(P(`The seasonal period of this series is 365 days. A SARIMA model with a seasonal lag of 365 is not practical with ten years of daily data, because the state-space form becomes very large and only seven seasonal cycles are available in the training set. We tried two alternatives.`));
c.push(P(`The first is ${sar}, a weekly seasonal model of the kind often applied to daily data. It gave an RMSE of ${f(R[sar].RMSE)} °C, slightly worse than the plain ARIMA, and a higher AIC (${f(S.aic[sar], 0)} against ${f(S.aic[arima], 0)}). The estimated seasonal AR and MA coefficients are ${f(S.sarima_params['ar.S.L7'][0])} and ${f(S.sarima_params['ma.S.L7'][0])}; they are nearly equal and of opposite sign, so they almost cancel each other. The model is telling us what Figure 4 already showed: there is no weekly cycle in night temperatures to capture. We report the model because it shows that a seasonal term only helps when it matches a period that exists in the data.`));
c.push(P(`The second alternative handles the annual cycle directly. We added two pairs of sine and cosine terms with a period of 365.25 days as regressors and modelled what is left with ARIMA(2,0,1), with no differencing. This is the levels approach described in Section 2.5. It has the lowest AIC of all the classical models (${f(S.aic[four], 0)}) and the lowest test error: RMSE ${f(R[four].RMSE)} °C, MAE ${f(R[four].MAE)} °C, R² ${f(R[four].R2, 3)}. In Figure 9 the forecast line is centred on the observations in winter, where MA(7) sat too high.`));
FIG('06_sarima_forecast.png', 6.5, sizeOf('06_sarima_forecast.png'), `**Figure 9.** ${four}: one-step-ahead forecasts against actual values.`).forEach(x => c.push(x));
c.push(H2('3.6 Results'));
c.push(TCAP(`**Table 4.** One-step-ahead performance on the test set (${S.split.test[0]} days). Lowest error in bold.`));
const lab = { Climatology: 'Climatology (baseline)', Persistence: 'Persistence (baseline)' };
c.push(TBL([3600, 1250, 1250, 1350, 1250], [['Model', 'RMSE (°C)', 'MAE (°C)', 'MAPE (%)', 'R²'],
  ...S.order.map(k => [lab[k] || k, f(R[k].RMSE), f(R[k].MAE), f(R[k].MAPE, 1), f(R[k].R2, 3)])], [S.order.indexOf(four) + 1]));
c.push(SP());
FIG('11_rmse_comparison.png', 6.3, sizeOf('11_rmse_comparison.png'), '**Figure 10.** Test RMSE of all models. Light grey: baselines. Dark grey: classical. Red: neural.').forEach(x => c.push(x));
c.push(P(`Table 4 includes the neural models of Section 4 so that all results can be read together. Three things stand out. First, every fitted model beats persistence, and the gain from persistence (${f(R.Persistence.RMSE)} °C) to the best model (${f(R[four].RMSE)} °C) is about ${f((1 - R[four].RMSE / R.Persistence.RMSE) * 100, 0)}%. Second, five models, AR(14), ${arima}, the weekly SARIMA, the RNN and the LSTM, lie within 0.02 °C of each other at about 2.24 °C. Third, the only model that separates itself from that group is the one that was given the annual cycle explicitly, and even that gain is only 0.05 °C. The error seems to have a floor a little above 2 °C when the only input is the temperature history, which is consistent with the 2.5 °C remainder found in the decomposition.`));

// 4
c.push(H1('4. Neural Network Models'));
c.push(H2('4.1 Set-up'));
c.push(P(`The neural models take a window of the previous L days as input and output the next day's value, so they are also one-step-ahead forecasters. The series was scaled to the range 0 to 1 with the minimum and maximum of the training set only, so that no information from validation or test data enters the scaling. Windows for the first validation and test days reach back into the preceding set, which means every validation and test day receives a forecast and the test window is exactly the same ${S.split.test[0]} days used for the classical models. Both networks were trained with mean squared error and the Adam optimiser for up to 40 epochs, with early stopping (patience of six epochs) on the validation loss and the best weights restored. The random seed was fixed, and a second complete run reproduced every number in this report exactly.`));
c.push(H2('4.2 Tuning on the validation set'));
c.push(P(`We searched lag window (7, 14, 30 days), number of units (32, 64) and learning rate (0.001, 0.003) in a full grid of twelve combinations with one recurrent layer and batch size 32. Starting from the best of these, we then tried a second recurrent layer and batch sizes of 16 and 64. This gave fifteen configurations per architecture, each scored by RMSE on the validation set (Table 5 and Figure 11).`));
c.push(TCAP('**Table 5.** Validation RMSE (°C) for the twelve grid configurations (one layer, batch size 32). Selected settings in bold.'));
const tr = S.tuning.RNN.slice(0, 12).map((r, i) => [r.lag, r.units, r.lr, f(r.val_RMSE, 3), f(S.tuning.LSTM[i].val_RMSE, 3)]);
c.push(TBL([1500, 1500, 1700, 1700, 1700], [['Lag (days)', 'Units', 'Learning rate', 'RNN', 'LSTM'], ...tr], [9, 11]));
c.push(SP());
FIG('08b_tuning.png', 6.5, sizeOf('08b_tuning.png'), '**Figure 11.** Validation RMSE by lag window, units and learning rate.').forEach(x => c.push(x));
const bR = S.best_cfg.RNN, bL = S.best_cfg.LSTM, tR = S.tuning.RNN, tL = S.tuning.LSTM;
c.push(P(`The selected RNN has a lag of ${bR.lag} days, ${bR.units} units, one layer, learning rate ${bR.lr} and batch size ${bR.batch} (validation RMSE ${f(bR.val_RMSE, 3)} °C). The selected LSTM has a lag of ${bL.lag} days, ${bL.units} units, one layer, learning rate ${bL.lr} and batch size ${bL.batch} (${f(bL.val_RMSE, 3)} °C). Our observations from the search are these.`));
c.push(B(`**The tuning surface is flat.** Across all fifteen RNN settings the validation RMSE ranges from ${f(Math.min(...tR.map(r => r.val_RMSE)), 2)} to ${f(Math.max(...tR.map(r => r.val_RMSE)), 2)} °C; for the LSTM the range is ${f(Math.min(...tL.map(r => r.val_RMSE)), 2)} to ${f(Math.max(...tL.map(r => r.val_RMSE)), 2)} °C. No setting changes the result by more than about 0.1 °C.`));
c.push(B(`**The LSTM benefits from a longer window; the RNN does not do so reliably.** In Figure 11 all four LSTM lines fall as the lag grows from 7 to 30 days. The RNN lines cross each other, and with the larger learning rate the 30-day window is the worst setting. A simple RNN finds long sequences harder to train, which is the weakness the LSTM was designed to remove.`));
c.push(B(`**The lower learning rate is safer.** With 0.003 the RNN often stopped after eight or nine epochs at a worse validation loss. With 0.001 the best LSTM was still improving slowly at epoch 40.`));
c.push(B(`**Depth and batch size did not help.** A second layer gave ${f(tR[12].val_RMSE, 3)} °C for the RNN and ${f(tL[12].val_RMSE, 3)} °C for the LSTM, both worse than one layer. Batch size 64 was slightly worse for both, and batch size 16 was clearly worse for the LSTM (${f(tL[14].val_RMSE, 3)} °C).`));
c.push(H2('4.3 Test results'));
c.push(P(`On the test set the RNN has RMSE ${f(R.RNN.RMSE)} °C, MAE ${f(R.RNN.MAE)} °C, MAPE ${f(R.RNN.MAPE, 1)}% and R² ${f(R.RNN.R2, 3)}. The LSTM has RMSE ${f(R.LSTM.RMSE)} °C, MAE ${f(R.LSTM.MAE)} °C, MAPE ${f(R.LSTM.MAPE, 1)}% and R² ${f(R.LSTM.R2, 3)}. The two are indistinguishable from each other and from AR(14) and ${arima} (Figures 12 and 13).`));
FIG('07_rnn_forecast.png', 6.5, sizeOf('07_rnn_forecast.png'), '**Figure 12.** RNN one-step-ahead forecasts against actual values.').forEach(x => c.push(x));
FIG('08_lstm_forecast.png', 6.5, sizeOf('08_lstm_forecast.png'), '**Figure 13.** LSTM one-step-ahead forecasts against actual values.').forEach(x => c.push(x));
c.push(H2('4.4 Why the networks did not beat the linear models'));
c.push(P(`We expected the neural networks to win and they did not. We think the explanation lies in the data, not in the tuning. The project brief notes that linear models capture only linear dependence and neural networks can capture non-linear relations. That advantage only shows when a non-linear relation is present in the inputs. Here the single input is the past of the temperature itself, and the ARIMA residuals are already white noise (Section 3.4), so there is very little structure left for a more flexible model to find. The flat tuning surface points the same way: if there were more to learn, a larger network or a longer window would have helped.`));
c.push(P(`The winter zoom panels of Figures 12 and 13 show a second point. The forecast lines are smoother than the observations and lag the sharp drops by a day. All the models behave like this. Sudden cold nights in Melbourne are caused by clear skies and the passage of cold fronts, and neither is visible in yesterday's minimum. To improve substantially on 2.2 °C the model would need other inputs, such as cloud cover, wind, dew point or a numerical weather forecast, not a different architecture.`));
c.push(P(`For the decision this is a useful result. The linear model is as accurate as the networks, trains in seconds, has a handful of coefficients that can be inspected, and gives the same answer every time it is fitted.`));

// 5
c.push(H1('5. Probabilistic Forecast'));
c.push(P(`A point forecast gives no indication of how wrong it might be. For the interval forecast we trained LSTM models with the pinball loss, which for a target quantile τ penalises under-prediction with weight τ and over-prediction with weight 1 − τ. Minimising it drives the output towards the τ-quantile of the conditional distribution. One network was trained for τ = 0.025 and one for τ = 0.975; together they give a nominal 95% prediction interval. Both use the architecture selected in Section 4 (lag ${bL.lag}, ${bL.units} units, one layer) and early stopping on the validation pinball loss. We trained three further networks at τ = 0.10, 0.25 and 0.40 for use in the decision analysis.`));
FIG('09_prediction_interval.png', 6.5, sizeOf('09_prediction_interval.png'), '**Figure 14.** 95% prediction interval from the quantile LSTMs against actual values. Red points fall outside the interval.').forEach(x => c.push(x));
c.push(P(`On the test set the prediction interval coverage probability (PICP) is ${f(I.PICP * 100, 1)}%: ${Math.round(I.PICP * S.split.test[0])} of ${S.split.test[0]} nights fall inside the interval. The mean prediction interval width (MPIW) is ${f(I.MPIW, 2)} °C. On the validation set the coverage was ${f(I.PICP_val * 100, 1)}%, so the interval is well calibrated on both sets. Of the ${I.below + I.above} test nights outside the interval, ${I.below} were below the lower bound and ${I.above} above the upper bound, an almost even split. The two quantile curves never cross.`));
c.push(TCAP('**Table 6.** Calibration of the quantile LSTMs on the test set.'));
c.push(TBL([3300, 3300], [['Target quantile τ', 'Share of nights below the forecast'], ...Object.keys(I.cov_below).map(k => [f(k, 3), f(I.cov_below[k] * 100, 1) + '%'])]));
c.push(SP());
c.push(P(`Table 6 checks each quantile separately. The outer quantiles are close to target. The middle ones sit a little low: only ${f(I.cov_below['0.25'] * 100, 1)}% of nights fell below the 0.25 quantile and ${f(I.cov_below['0.4'] * 100, 1)}% below the 0.40 quantile. In other words these forecasts are somewhat colder than they should be, which makes any plan based on them slightly more cautious than intended.`));
c.push(P(`Our main observation concerns the width. The interval is between ${f(I.width_min, 1)} and ${f(I.width_max, 1)} °C wide on every night of the test period, and its mean width is nearly the same in winter (${f(I.width_winter, 1)} °C) as in summer (${f(I.width_summer, 1)} °C). The band in Figure 14 moves up and down with the season and with recent days, but it does not narrow on nights that are easy to forecast or widen on nights that are hard. That is what one would expect when the model has no input that signals an unstable night. An interval of ±5 °C around a quantity whose whole annual range is about 25 °C is honest but not sharp. It is reliable as a statement of risk, and Section 7 shows that it is expensive to act on directly.`));

// 6
c.push(H1('6. From Forecast to Action'));
c.push(H2('6.1 The planning rule'));
c.push(P(`Each afternoon the operator takes a planning temperature T for the coming night and books max(8 − T, 0) degrees of heating. The planning temperature can be a point forecast or a quantile. When the morning reading arrives, the cost for the night is $12 per planned degree plus $30 per degree of shortfall. We applied this rule to every night of the test period for each candidate forecast. Table 7 and Figure 15 give the results. The total heating need in the period was ${f(S.need_deg_total, 1)} degree-nights spread over ${S.test_stats.days_below_8} nights.`));
c.push(TCAP(`**Table 7.** Heating cost over the ${S.split.test[0]}-day test period by planning rule. An emergency night is one on which the plan fell short of the need.`));
const crow = k => [k.replace('tau', 'τ'), money(C[k].planned), money(C[k].emergency), money(C[k].total), C[k].emerg_nights, f(C[k].wasted_deg, 0)];
c.push(TBL([3300, 1150, 1250, 1150, 1250, 1250], [['Planning rule', 'Planned', 'Emergency', 'Total', 'Emergency nights', 'Wasted degree-nights'], ...Object.keys(C).map(crow)], [Object.keys(C).indexOf(four) + 1]));
c.push(SP());
FIG('10_cost_comparison.png', 6.5, sizeOf('10_cost_comparison.png'), '**Figure 15.** Total heating cost by planning rule, split into planned and emergency heating.').forEach(x => c.push(x));
c.push(H2('6.2 What the forecast changes'));
c.push(P(`**Without a forecast** the operator can only plan for the average night. The average minimum is 11 °C, above the threshold, so nothing is booked and every cold night becomes an emergency: ${C['No forecast (climatology)'].emerg_nights} call-outs and ${money(base)}, all of it at the emergency rate.`));
c.push(P(`**With persistence** (plan for a repeat of last night) the cost falls to ${money(C['Persistence (yesterday)'].total)}, a saving of only ${money(base - C['Persistence (yesterday)'].total)}. Persistence over-reacts. It books heat after a cold night that is not followed by another and books none after a mild night that is followed by a cold one, and it wastes ${f(C['Persistence (yesterday)'].wasted_deg, 0)} degree-nights of planned heat, more than any other point forecast.`));
c.push(P(`**With a fitted model** the cost falls to between ${money(C[four].total)} and ${money(C['RNN point forecast'].total)}. The five models are within $${Math.round(C['RNN point forecast'].total - C[four].total)} of each other, which is 0.5% of the bill, so on cost as on accuracy there is nothing to choose between them. The recommended model, ${four}, gives ${money(C[four].total)}: a saving of ${money(base - C[four].total)} or ${f((base - C[four].total) / base * 100, 1)}% against no forecast, and ${money(C['Persistence (yesterday)'].total - C[four].total)} against persistence. Emergency nights fall from ${C['No forecast (climatology)'].emerg_nights} to ${C[four].emerg_nights}, and the degrees supplied at the emergency rate fall from ${f(C['No forecast (climatology)'].short_deg, 0)} to ${f(C[four].short_deg, 0)}.`));
c.push(P(`So the action that changes is this: instead of waiting for the temperature to fall and reacting, the operator books about ${f(C[four].planned / 12, 0)} degree-nights of heating in advance over the period, at the cheap rate, on the nights the model flags. Scaled to a year the saving is about ${money((base - C[four].total) / S.split.test[0] * 365)} per unit of heating load. The cost model is linear, so a site with ten times the load saves ten times as much.`));
c.push(P(`**Perfect foresight** would cost ${money(C['Perfect foresight'].total)}. The gap between no forecast and a perfect forecast is ${money(base - C['Perfect foresight'].total)}, and the recommended model closes ${f((base - C[four].total) / (base - C['Perfect foresight'].total) * 100, 0)}% of it. Most of the possible saving is still out of reach. The reason is visible in the emergency-night column: even with the best model the plan falls short on ${C[four].emerg_nights} of the ${S.test_stats.days_below_8} cold nights. On nights that turned out below 8 °C the recommended model's forecast was on average ${f(Math.abs(S.err.cold_bias), 1)} °C too warm. This is not a fault that tuning can remove. A forecast that minimises squared error is pulled towards the middle of the distribution, so on the coldest nights it is systematically too mild, and those are exactly the nights that cost money.`));
c.push(H2('6.3 Which quantile should the operator plan to?'));
c.push(P(`Because under-heating costs more than over-heating, it seems sensible to plan for a night somewhat colder than the central forecast. The cost model gives an exact answer. Booking one more degree costs $12 for certain and saves $30 if that degree turns out to be needed, so it is worth booking as long as the probability of needing it is above 12/30 = 0.40. The cost-minimising planning temperature is therefore the 0.40 quantile of the forecast distribution, only slightly below the median.`));
c.push(P(`We tested this with the τ = 0.40 quantile LSTM. It produced fewer emergency nights (${C['Quantile LSTM, tau = 0.40'].emerg_nights} against ${C['LSTM point forecast'].emerg_nights} for the LSTM point forecast) but a slightly higher total, ${money(C['Quantile LSTM, tau = 0.40'].total)} against ${money(C['LSTM point forecast'].total)}. The theoretical advantage did not appear in our data. Table 6 suggests why: this quantile forecast behaved like a 0.34 quantile, a little colder than intended, and with a penalty ratio of only 2.5 the optimum is so close to the centre that a small calibration error cancels the gain. Our conclusion is that with the cost assumptions of this project the point forecast is already close to the best plan, and there is no saving to be had from shading it.`));

// 7
c.push(H1('7. Risk and Reliability'));
c.push(H2('7.1 How wrong can the forecast be?'));
c.push(P(`The typical error of the recommended model is ${f(R[four].MAE, 1)} °C (MAE), and 95% of its absolute errors were below ${f(S.err.p95_abs, 1)} °C. The most expensive miss was on ${S.err.worst_date}. The forecast was ${f(S.err.worst_pred, 1)} °C, just above the threshold, so no heating was booked. The night fell to ${f(S.err.worst_actual, 1)} °C. The shortfall of ${f(S.err.worst_short, 1)} degrees cost $${Math.round(S.err.worst_short * 30)} in emergency heat, against the $${Math.round((8 - S.err.worst_actual) * 12)} it would have cost if booked in advance. This one night can be seen at the right-hand edge of the zoom panels in Figures 13 and 14, and it is also one of the ${I.below} nights that fell below the 95% interval.`));
c.push(P(`Over the whole test period, planning on the recommended point forecast left ${money(C[four].emergency)} of emergency cost. In a statistical sense that figure is the price of forecast error under our cost model: it is ${f(C[four].emergency / C[four].total * 100, 0)}% of the total bill.`));
c.push(H2('7.2 Using the interval to buy reliability'));
c.push(P(`The prediction interval turns into action through its lower bound. If the operator plans to the 0.025 quantile, the plan is too small only when the night is colder than a level that should be undercut on 2.5% of nights. In the test period the actual temperature fell below the lower bound on ${I.below} nights (${f(I.below / S.split.test[0] * 100, 1)}%), and on ${C['Lower bound every night (tau = 0.025)'].emerg_nights} of them the plan fell short of the heating need. The breaches were small: the mean was ${f(I.mean_breach_below, 1)} °C and the largest ${f(I.max_breach_below, 1)} °C. A fixed safety margin of 1.5 °C added to the lower-bound plan would have covered every night in the test set. Emergency cost drops from ${money(C['LSTM point forecast'].emergency)} to ${money(C['Lower bound every night (tau = 0.025)'].emergency)}.`));
c.push(P(`The price of that reliability is high. The lower bound is about 5 °C below the central forecast, so heat is booked on most nights in the cooler half of the year, including many that never come near 8 °C. Planned cost rises to ${money(C['Lower bound every night (tau = 0.025)'].planned)} and the total to ${money(C['Lower bound every night (tau = 0.025)'].total)}, more than twice the cost of having no forecast at all. The operator pays about ${money(C['Lower bound every night (tau = 0.025)'].total - C['LSTM point forecast'].total)} to avoid ${C['LSTM point forecast'].emerg_nights - C['Lower bound every night (tau = 0.025)'].emerg_nights} emergency nights, roughly $${Math.round((C['Lower bound every night (tau = 0.025)'].total - C['LSTM point forecast'].total) / (C['LSTM point forecast'].emerg_nights - C['Lower bound every night (tau = 0.025)'].emerg_nights))} per emergency avoided.`));
c.push(P(`Whether that is worth paying depends on what an unplanned cold night really costs. Table 8 gives the break-even point for each quantile: the emergency multiplier at which planning to that quantile costs the same as planning to the LSTM point forecast.`));
const m = C['LSTM point forecast'];
const be = k => (C[k].planned - m.planned) / (12 * (m.short_deg - C[k].short_deg));
const qk = ['Quantile LSTM, tau = 0.40', 'Quantile LSTM, tau = 0.25', 'Quantile LSTM, tau = 0.10', 'Lower bound every night (tau = 0.025)'];
c.push(TCAP('**Table 8.** Reliability ladder: cost and emergency nights by planning quantile, with the emergency multiplier at which each becomes cheaper than the point forecast.'));
c.push(TBL([2300, 1500, 1700, 1700, 2100], [['Planning quantile τ', 'Total cost', 'Emergency nights', 'Emergency cost', 'Break-even multiplier'],
  ['Point forecast (LSTM)', money(m.total), m.emerg_nights, money(m.emergency), '–'],
  ...qk.map((k, i) => [['0.40', '0.25', '0.10', '0.025 (lower bound)'][i], money(C[k].total), C[k].emerg_nights, money(C[k].emergency), f(be(k), 1) + '×'])]));
c.push(SP());
c.push(P(`The table reads as a ladder. At our assumed multiplier of 2.5 no rung beats the point forecast. If an unplanned shortfall costs about four times the normal rate, planning to the 0.25 quantile becomes worthwhile, and it roughly halves the emergency nights (${C['Quantile LSTM, tau = 0.25'].emerg_nights} against ${m.emerg_nights}). Above about six times, the 0.10 quantile pays. Only when the multiplier passes about ${f(be(qk[3]), 0)} does it make sense to plan to the lower bound of the 95% interval every night.`));
c.push(H2('7.3 A policy for the operator'));
c.push(P(`These results lead to a rule that an operator can follow without any knowledge of the models.`));
c.push(B(`**Ordinary nights.** Plan on the point forecast. A shortfall means running stand-by heaters at a higher rate, which is an inconvenience and a cost of $30 per degree, and the point forecast gives the lowest total bill.`));
c.push(B(`**Sensitive nights.** When a shortfall would be costly but recoverable, for example young plants or stock that degrades in the cold, plan to the 0.25 or 0.10 quantile. Expect the heating bill to rise by about a quarter to a factor of two in exchange for cutting emergency nights from ${m.emerg_nights} to ${C['Quantile LSTM, tau = 0.25'].emerg_nights} or ${C['Quantile LSTM, tau = 0.10'].emerg_nights}.`));
c.push(B(`**Critical nights.** When a shortfall would mean a loss many times the cost of heating, such as a frost-sensitive crop close to harvest, plan to the lower bound of the interval plus a 1.5 °C margin. On the evidence of the test period this would have left no night uncovered.`));
c.push(P(`The quantified risk in our example is therefore as follows. On the point forecast, the plan falls short on about ${f(C[four].emerg_nights / S.test_stats.days_below_8 * 100, 0)}% of cold nights, by ${f(C[four].short_deg / C[four].emerg_nights, 1)} degrees on average. On the lower bound it falls short on ${f(C['Lower bound every night (tau = 0.025)'].emerg_nights / S.split.test[0] * 100, 1)}% of all nights, by about one degree. The interval does not make the forecast more accurate. What it does is let the operator choose, in advance and with known odds, how much to pay to move from the first position towards the second.`));

// 8
c.push(H1('8. Management Assessment'));
c.push(P(`**Effectiveness.** The forecast does what it was built for, to a limited degree. It turns ${f((1 - C[four].emerg_nights / C['No forecast (climatology)'].emerg_nights) * 100, 0)}% of emergency call-outs into planned heating and lowers the bill by ${f((base - C[four].total) / base * 100, 0)}%. It does not come close to removing emergency heating, and a manager should not be told that it will. About ${f(C[four].emergency / C[four].total * 100, 0)}% of the remaining bill is still paid at the emergency rate.`));
c.push(P(`**Worth.** Per unit of heating load the saving is about ${money((base - C[four].total) / S.split.test[0] * 365)} a year. Whether that justifies the effort depends on scale. For a single small glasshouse it probably does not cover the time needed to maintain the system. For a site with fifty times the load, the same percentage is about ${money((base - C[four].total) / S.split.test[0] * 365 * 50)} a year from a model that needs one temperature reading a day and no special hardware. The saving in labour may matter as much as the saving in money: ${C['No forecast (climatology)'].emerg_nights - C[four].emerg_nights} fewer night call-outs over eighteen months.`));
c.push(P(`**Cost of running it.** The recommended model has eight coefficients and is fitted in a few seconds on a laptop. It needs the previous days' minimum temperatures and the date. Refitting once a year with the latest data is enough, since the decomposition found no drift in the climate over the decade that would make the coefficients go stale quickly.`));
c.push(P(`**What we would not recommend.** We would not deploy the RNN or LSTM for the point forecast. They are as accurate as the linear model but no more, they take longer to train, and they are harder to explain to the person who has to trust the number. We would also not plan to the lower bound of the interval as a routine. It more than doubles the bill and is justified only for nights when a shortfall would be very costly.`));
c.push(P(`**Where the next gain is.** The models have taken nearly everything that the temperature history can give. The remaining ${money(C[four].total - C['Perfect foresight'].total)} between our result and perfect foresight can only be reduced with new information. The first step we would take is to add the weather service's forecast minimum for the coming night as an input. That is the single change most likely to shorten both the error and the interval, and the framework of this report (same split, same cost model, same tables) can measure exactly how much it is worth.`));

// 9
c.push(H1('9. Limitations'));
c.push(B(`**The cost model is assumed.** The threshold, the $12 rate and the 2.5 multiplier are illustrative. The percentage saving and the break-even multipliers depend on them. The ranking of the planning rules is less sensitive, and Table 8 shows how it changes with the multiplier.`));
c.push(B(`**The cost is linear in degrees.** Real heating systems have capacity limits and start-up costs, and real damage from cold is not proportional to the shortfall. A crop may be unharmed at 6 °C and lost at 0 °C.`));
c.push(B(`**One test period.** The test set covers eighteen months and one and a half winters. The differences among the five best models are far smaller than the variation we would expect from one winter to another, so we do not claim that the recommended model is truly better than the others, only that it is at least as good and simpler.`));
c.push(B(`**Model choice and the test set.** Neural network settings were chosen on the validation set. The classical orders were chosen from the ACF, PACF and AIC on the training set. The final recommendation among models, however, was made after seeing test results, which makes the reported error of the recommended model slightly optimistic.`));
c.push(B(`**Fixed coefficients.** The classical models were not re-estimated as the test period advanced. In operation they would be refitted periodically, which should help a little.`));
c.push(B(`**Single input.** All models use only the temperature history. Section 4.4 explains why we think this, not the choice of model, limits the accuracy.`));
c.push(B(`**Old data from one site.** The series ends in 1990 and refers to one station. The method transfers to other places and periods; the numbers do not.`));

// 10
c.push(H1('10. Conclusion'));
c.push(P(`We forecast the daily minimum temperature in Melbourne one day ahead with nine models on a common chronological split. The series is stationary around a strong annual cycle, with short weather memory of about a week and no weekly pattern. Under a fair one-step-ahead comparison the classical and neural models perform almost identically, with RMSE between ${f(R[four].RMSE)} and ${f(R[sar].RMSE)} °C for all but the MA model, and the best result comes from a small ARIMA model with annual sine and cosine terms. Tuning the RNN and LSTM changed their validation error by no more than 0.1 °C.`));
c.push(P(`Translated into the heating decision, the forecast reduces the bill for the test period from ${money(base)} to ${money(C[four].total)} and the number of emergency nights from ${C['No forecast (climatology)'].emerg_nights} to ${C[four].emerg_nights}. The quantile LSTMs give a 95% interval with ${f(I.PICP * 100, 1)}% coverage and a width of ${f(I.MPIW, 1)} °C. Planning to its lower bound nearly eliminates emergencies but costs ${money(C['Lower bound every night (tau = 0.025)'].total)}, so it should be kept for nights when a shortfall would cost more than about eight times the normal rate.`));
c.push(P(`The lesson we take from the project is that the evaluation protocol and the cost model shaped our conclusions more than the choice of model did. Our first comparison, which mixed multi-step and one-step forecasts, pointed to the RNN as the clear winner. The corrected comparison points to the simplest model that knows about the season. And it was the cost calculation, not the error metrics, that showed where the money is lost: on cold nights that no model in our set could see coming.`));

